7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  76) Classifier_read (Classifier* out, const uint8_t** ptr, size_t* size)
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  77) {
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  78)     const uint8_t* curin = *ptr;
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  79)     size_t         len   = 0;
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  80)     uint8_t        value;
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  81)     uint8_t        type;
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  82)
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  83)     if (*size <= 3) return EXR_ERR_CORRUPT_CHUNK;
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  84)
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  85)     {
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  86)         // maximum length of string plus one byte for terminating NULL
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  87)         char  suffix[128 + 1];
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  88)         char* mem;
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  89)         memset (suffix, 0, 128 + 1);
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  90)         for (; len < 128 + 1; ++len)
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  91)         {
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  92)             if (len > (*size - 3)) return EXR_ERR_CORRUPT_CHUNK;
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  93)             if (curin[len] == '\0') break;
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  94)             suffix[len] = (char)curin[len];
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  95)         }
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  96)         len += 1;
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  97)         if (len == 128 + 1) return EXR_ERR_CORRUPT_CHUNK;
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  98)
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200  99)         mem = internal_exr_alloc (len);
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200 100)         if (!mem) return EXR_ERR_OUT_OF_MEMORY;
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200 101)
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200 102)         memcpy (mem, suffix, len);
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200 103)         out->_suffix       = mem;
7c40603eb (Kimball Thurston 2023-05-16 19:38:52 +1200 104)         out->_stringStatic = DWA_CLASSIFIER_FALSE;
